{"command": "/tmp/opensip-architecture-review-env/bin/python -I -B - <<'PY'
import json, base64, hashlib
from pathlib import Path
from jsonschema import Draft202012Validator

KIT=Path("/tmp/opensip-design-corrections/consumer-b.v12-kit-scope-review.v1/subject")
SNAP=Path("/tmp/opensip-design-corrections/consumer-b.v12-kit-scope-review.v1/consumer-snapshot")

def enc_null(): return bytes([0x00])
def enc_false(): return bytes([0x01])
def enc_true(): return bytes([0x02])
def enc_u64(n): return bytes([0x03]) + n.to_bytes(8,"big")
def enc_i64(n): return bytes([0x07]) + n.to_bytes(8,"big", signed=True)

cve=json.loads((SNAP/"vectors/cve1-eight-types.json").read_text())
checks=[]
for v in cve["vectors"]:
    t=v.get("type") or v.get("inputKind")
    if "committedBytesHex" not in v:
        checks.append({"skip": list(v.keys())}); continue
    claimed=bytes.fromhex(v["committedBytesHex"])
    if t=="null": got=enc_null()
    elif t=="false": got=enc_false()
    elif t=="true": got=enc_true()
    elif t=="unsigned-64": got=enc_u64(v["decoded"])
    elif t=="negative-signed-64": got=enc_i64(v["decoded"])
    else:
        checks.append({"type":t,"independent":False})
        continue
    checks.append({"type":t,"decoded":v.get("decoded"),"match":got==claimed})
print(json.dumps(checks, indent=2))
print("matches", sum(1 for c in checks if c.get("match")), "fail", [c for c in checks if c.get("match") is False])

st=json.loads((SNAP/"runs/ts.store.json").read_text())
scope_d=json.loads((SNAP/"runs/ts.meta.json").read_text())["scopeDocDigest"]
raw=base64.b64decode(st["blobs"][scope_d])
obj=json.loads(raw)
print("ScopeDocument", obj)
pol=json.loads((KIT/"docs/coop/design-corrections/workflows/schemas/policy-document.schema.json").read_text())
print("has ScopeDocumentV1", "ScopeDocumentV1" in pol.get("$defs",{}))
schema={"$schema":"https://json-schema.org/draft/2020-12/schema","$defs": pol.get("$defs",{}), **pol["$defs"]["ScopeDocumentV1"]}
errs=[e.message for e in Draft202012Validator(schema).iter_errors(obj)]
print("ScopeDocument stockOk", not errs, errs[:5])
pol_bytes=(KIT/"docs/coop/design-corrections/workflows/schemas/policy-document.schema.json").read_bytes()
print("policy-document sha match", hashlib.sha256(pol_bytes).hexdigest()=="012505da479197875602899c027b3d0daea9e23e01e490e3dc94bbe3d7062e18")

rr=json.loads((SNAP/"vectors/relation-rung-table.json").read_text())
print("pairCount", rr.get("pairCount"), "relationCount", rr.get("relationCount"), "nPairs", len(rr.get("pairs") or []))
cc=json.loads((SNAP/"vectors/count-class-attempt.json").read_text())
print("count-class keys", list(cc.keys())[:12], "nCases", len(cc.get("cases") or cc.get("vectors") or []))
PY", "description": "CVE1 remint, ScopeDocument schema, rung table counts"}
